  const tools=document.createElement('div');tools.className='ai-writing-tools';
  tools.innerHTML='<button type="button" class="secondary ai-improve">'+tr('Improve writing','Mejorar redacción')+'</button><button type="button" class="secondary ai-restore" disabled>'+tr('Restore original','Restaurar original')+'</button>';
  field.insertAdjacentElement('afterend',tools);
  const restore=tools.querySelector('.ai-restore'),sync=()=>restore.disabled=field.dataset.aiOriginal===undefined;
