function installFormSubmissionGuards(){
 for(const form of document.querySelectorAll('form')){
  if(!form.onsubmit||form.dataset.submitGuard==='true')continue;
  const submit=form.onsubmit;form.dataset.submitGuard='true';
  form.onsubmit=async event=>{
   event.preventDefault();if(form.dataset.operationBusy==='true')return;
   form.dataset.operationBusy='true';const buttons=[...form.querySelectorAll('button[type="submit"],button:not([type]),input[type="submit"]')],disabled=buttons.map(button=>button.disabled);
   buttons.forEach(button=>button.disabled=true);
   try{await submit.call(form,event)}catch(err){if(form.isConnected)error(err)}
   finally{delete form.dataset.operationBusy;buttons.forEach((button,i)=>button.disabled=disabled[i])}
  };
 }
}
