 const first=p.first_name||String(p.name||'').trim().split(/\s+/)[0]||'',last=p.last_name||String(p.name||'').trim().split(/\s+/).slice(1).join(' ');
 const full=[first,last].filter(Boolean).join(' ')||p.name||tr('My Profile','Mi Perfil'),initials=full.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
 const jobsite=state.projects.find(x=>x.id===p.jobsite_id);
 if(!viewCurrent())return;frame(`<section class="profile-shell"><div class="profile-card profile-card-pro"><header class="profile-pro-head"><div class="profile-avatar-wrap"><div id="profile-avatar-large" class="profile-avatar-large"></div><label class="profile-photo-button">📷 <span>${tr('Change photo','Cambiar foto')}</span><input id="profile-photo" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" hidden></label></div><div class="profile-info"><small>${tr('TEAM MEMBER PROFILE','PERFIL DEL INTEGRANTE')}</small><h1>${esc(full)}</h1><p>${esc(p.email||state.session?.user?.email||'')}</p><span>${esc((p.role||'worker').replaceAll('_',' '))}</span></div></header><form id="member-profile-form" class="profile-form"><div class="profile-form-grid"><label>${tr('First name','Nombre')}<input name="first_name" maxlength="60" required value="${esc(first)}"></label><label>${tr('Last name','Apellido')}<input name="last_name" maxlength="80" required value="${esc(last)}"></label><label>${tr('Position / Job title','Cargo / Posición')}<input name="position" maxlength="100" required value="${esc(p.position||'')}" placeholder="${tr('Example: Safety Coordinator','Ejemplo: Safety Coordinator')}"></label><label>${tr('Mobile phone','Teléfono móvil')}<input name="phone" type="tel" inputmode="tel" maxlength="20" value="${esc(p.phone||'')}" placeholder="+1 305 555 0123"></label><label>${tr('Primary Jobsite','Jobsite principal')}<select name="jobsite_id" required><option value="">${tr('Select jobsite','Seleccionar jobsite')}</option>${state.projects.map(x=>`<option value="${esc(x.id)}" ${x.id===p.jobsite_id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div><label class="profile-bio-label">${tr('About me','Acerca de mí')}<textarea name="bio" maxlength="500" placeholder="${tr('Write a short professional description about yourself, your experience or safety responsibilities.','Escribe una breve descripción profesional sobre ti, tu experiencia o responsabilidades de seguridad.')}">${esc(p.bio||'')}</textarea><small>${tr('Maximum 500 characters.','Máximo 500 caracteres.')}</small></label><div class="profile-notification-settings"><div><strong>${tr('Safety Notifications','Notificaciones de Safety')}</strong><small>${tr('Receive a 24-hour summary of new observations and cases that remain open.','Reciba cada 24 horas un resumen de observaciones nuevas y casos que continúan abiertos.')}</small></div><label><input type="checkbox" name="notify_sms" ${p.notify_sms!==false?'checked':''}> ${tr('SMS to my mobile phone every 24 hours','SMS a mi teléfono móvil cada 24 horas')}</label><label><input type="checkbox" name="notify_app" ${p.notify_app!==false?'checked':''}> ${tr('Notifications inside the app','Notificaciones dentro de la app')}</label><label><input type="checkbox" name="notify_email" ${p.notify_email!==false?'checked':''}> ${tr('Email notifications','Notificaciones por correo')}</label></div><div class="profile-summary"><div><small>${tr('COMPANY EMAIL','CORREO DE COMPAÑÍA')}</small><strong>${esc(p.email||state.session?.user?.email||'—')}</strong></div><div><small>${tr('SYSTEM ROLE','ROL DEL SISTEMA')}</small><strong>${esc((p.role||'worker').replaceAll('_',' '))}</strong></div><div><small>${tr('CURRENT JOBSITE','JOBSITE ACTUAL')}</small><strong>${esc(jobsite?.name||tr('Not assigned','No asignado'))}</strong></div></div><div id="profile-message" class="profile-message" aria-live="polite"></div><div class="profile-form-actions"><button type="submit">${tr('Save profile','Guardar perfil')}</button></div></form><div class="profile-note">${tr('Your profile information is used across G&E Safety reports and team activity. Your system role and permissions can only be changed by an administrator.','La información de tu perfil se utiliza en los reportes de G&E Safety y la actividad del equipo. Tu rol y permisos del sistema solo pueden ser cambiados por un administrador.')}</div></div></section>`);
 const av=document.querySelector('#profile-avatar-large');if(avatar){const im=document.createElement('img');im.src=avatar;im.alt=tr('Profile photo','Foto de perfil');av.appendChild(im)}else av.textContent=initials;
 const msg=document.querySelector('#profile-message');
 document.querySelector('#member-profile-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]'),d=new FormData(e.target),firstName=String(d.get('first_name')||'').trim(),lastName=String(d.get('last_name')||'').trim(),position=String(d.get('position')||'').trim(),jobsiteId=String(d.get('jobsite_id')||'').trim(),bio=String(d.get('bio')||'').trim(),phone=String(d.get('phone')||'').trim(),notifySms=d.get('notify_sms')==='on',notifyApp=d.get('notify_app')==='on',notifyEmail=d.get('notify_email')==='on';if(phone&&!/^\+?[0-9 ()-]{10,20}$/.test(phone))return error(tr('Enter a valid mobile phone number including area code.','Ingrese un número móvil válido incluyendo código de área.'));if(notifySms&&!phone)return error(tr('Add a mobile phone number to enable SMS notifications.','Agregue un teléfono móvil para activar notificaciones SMS.'));if(!firstName||!lastName||!position||!jobsiteId)return error(tr('Complete all profile fields.','Completa todos los campos del perfil.'));b.disabled=true;msg.textContent=tr('Saving profile…','Guardando perfil…');const changes={first_name:firstName,last_name:lastName,name:firstName+' '+lastName,position,jobsite_id:jobsiteId,bio,phone:phone||null,notify_sms:notifySms,notify_app:notifyApp,notify_email:notifyEmail,updated_at:new Date().toISOString()};const saved=await db.from('profiles').update(changes).eq('id',p.id).select('*').single();b.disabled=false;if(saved.error){msg.textContent=saved.error.message;return}state.profile=saved.data;savedAction('Profile saved successfully.','Perfil guardado correctamente.');msg.textContent=tr('Profile saved successfully.','Perfil guardado correctamente.');setTimeout(()=>profilePage(),500)};
 document.querySelector('#profile-photo').onchange=async e=>{let file=e.target.files?.[0];if(!file)return;const allowed=['image/jpeg','image/png','image/webp','image/heic','image/heif'];if(file.size>5242880){msg.textContent=tr('Photo must be 5 MB or smaller.','La foto debe ser de 5 MB o menos.');return}if(!allowed.includes(file.type)&&!/\.hei[cf]$/i.test(file.name)){msg.textContent=tr('Choose a JPG, PNG, WEBP or HEIC image.','Elige una imagen JPG, PNG, WEBP o HEIC.');return}msg.textContent=tr('Preparing photo…','Preparando foto…');try{file=await normalizeReportImage(file)}catch(err){msg.textContent=err?.message||tr('Could not prepare this photo.','No se pudo preparar esta foto.');return}try{file=await cropProfilePhoto(file)}catch(err){msg.textContent=tr('Could not open the photo editor.','No se pudo abrir el editor de foto.');return}if(!file){msg.textContent=tr('Photo change canceled.','Cambio de foto cancelado.');return}if(file.size>5242880){msg.textContent=tr('Converted photo is larger than 5 MB. Choose another photo.','La foto convertida supera 5 MB. Elige otra foto.');return}msg.textContent=tr('Uploading photo…','Subiendo foto…');const ext=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,''),path=p.id+'/avatar-'+Date.now()+'.'+ext;const up=await db.storage.from('profile-avatars').upload(path,file,{contentType:file.type||'image/jpeg',cacheControl:'3600',upsert:false});if(up.error){msg.textContent=up.error.message;return}const old=p.avatar_path,saved=await db.from('profiles').update({avatar_path:path,updated_at:new Date().toISOString()}).eq('id',p.id).select('*').single();if(saved.error){await db.storage.from('profile-avatars').remove([path]);msg.textContent=saved.error.message;return}if(old)await db.storage.from('profile-avatars').remove([old]);state.profile=saved.data;savedAction('Profile photo saved.','Foto de perfil guardada.');profilePage()};
