function setPassword(){frame(`<section class="card narrow"><h1>${tr('Settings','Configuración')}</h1><label>${tr('Language','Idioma')}<select id="settings-language"><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="es" ${state.lang==='es'?'selected':''}>Español</option></select></label><div class="settings-weather"><div><strong>${tr('Gemini Writing Assistant','Asistente de redacción con Gemini')}</strong><small>${tr('Writing proposals for notes and comments across the app. Free tier has usage limits; Google may use the submitted text to improve its products. Avoid confidential details.','Propuestas de redacción para notas y comentarios en toda la app. El nivel gratuito tiene límites; Google puede usar el texto enviado para mejorar sus productos. Evita datos confidenciales.')}</small></div><label class="settings-switch"><input id="ai-writing-toggle" type="checkbox" ${aiWritingEnabled()?'checked':''}><span></span></label></div><p id="ai-writing-status" class="ai-settings-status" role="status">${tr('Checking connection…','Comprobando conexión…')}</p><h2>${tr('Password','Contraseña')}</h2><form id="password-form"><label>${tr('New password','Nueva contraseña')}<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><label>${tr('Confirm password','Confirmar contraseña')}<input type="password" name="confirmation" required minlength="8" autocomplete="new-password"></label><button>${tr('Save password','Guardar contraseña')}</button></form><div class="settings-weather"><div><strong>${tr('Session','Sesión')}</strong></div><button id="settings-signout" type="button" class="secondary">${tr('Sign Out','Cerrar sesión')}</button></div></section>`);document.querySelector('#settings-language').onchange=e=>{flushActiveDrafts();state.lang=e.target.value;localStorage.setItem('ge_lang',state.lang);savedAction('Language preference saved.','Preferencia de idioma guardada.');render()};document.querySelector('#ai-writing-toggle').onchange=e=>{localStorage.setItem('ge_ai_writing',e.target.checked?'on':'off');savedAction('Writing assistant preference saved.','Preferencia del asistente de redacción guardada.')};refreshAiWritingStatus(document.querySelector('#ai-writing-status'));document.querySelector('#settings-signout').onclick=async e=>{const button=e.currentTarget;button.disabled=true;try{const result=await db.auth.signOut();if(result.error)error(result.error)}catch(err){error(err)}finally{if(button.isConnected)button.disabled=false}};document.querySelector('#password-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),p=String(f.get('password'));if(p!==f.get('confirmation'))return error(tr('Passwords do not match','Las contraseñas no coinciden'));const {error:err}=await db.auth.updateUser({password:p});if(err)return error(err);savedAction('Password updated successfully.','Contraseña actualizada correctamente.');state.page='home';await refresh()}}
function renderRecovery(errorValue){console.error('[G&E Safety] app recovery boundary',errorValue);const message=esc(errorValue?.message||tr('A temporary connection error interrupted loading.','Un error temporal de conexión interrumpió la carga.'));frame(`<section class="card app-recovery"><h1>${tr('Dashboard temporarily unavailable','Panel temporalmente no disponible')}</h1><p>${message}</p><button id="app-retry" class="primary">${tr('Retry','Intentar de nuevo')}</button></section>`);const retry=document.querySelector('#app-retry');if(retry)retry.onclick=()=>refresh()}
async function refresh(){try{const auth=await db.auth.getSession();state.session=auth?.data?.session||null;await load();render()}catch(e){renderRecovery(e)}}
async function load(){
 if(!state.session){state.profile=null;state.projects=[];state.observations=[];return}
 const userId=state.session.user.id;
 const [p,projects,obs]=await Promise.all([
  db.from('profiles').select('*').eq('id',userId).maybeSingle(),
  db.from('projects').select('*').order('name'),
  db.from('observations').select('*, creator:profiles!observations_created_by_fkey(name), assignee:profiles!observations_assigned_to_fkey(name), foreman:profiles!observations_foreman_id_fkey(name), jobsite_safety:profiles!observations_jobsite_safety_id_fkey(name)').order('created_at',{ascending:false})
 ]);
 if(state.session?.user?.id!==userId)return;
 if(p.error)throw p.error;
 state.profile=p.data;if(!p.data)return;
 if(projects.error||obs.error)throw(projects.error||obs.error);
 state.projects=projects.data||[];state.observations=obs.data||[];
 if(!state.projects.some(x=>x.id===state.project))state.project=state.projects[0]?.id||null;
}

