function inventoryReportRecord(item,index){
 const fields=[
  [tr('Category','Categoría'),inventoryLabel(item.category)],
  [tr('Quantity','Cantidad'),item.quantity??'—'],
  [tr('Condition','Condición'),inventoryCondition(item.condition)],
  [tr('Operational status','Estado operacional'),inventoryOperationalStatus(item.status)],
  [tr('Location','Ubicación'),item.location],
  [tr('Assigned to','Asignado a'),item.assigned_to],
  [tr('Brand / Model','Marca / Modelo'),[item.brand,item.model].filter(Boolean).join(' / ')],
  [tr('Asset / ID','Asset / ID'),item.asset_id],
  [tr('Serial number','Número de serie'),item.serial_number],
  [tr('Last inspection','Última inspección'),item.last_inspection_at?localDateKey(item.last_inspection_at):null],
  [tr('Next inspection','Próxima inspección'),item.next_inspection_date]
 ];
 return '<section class="inventory-record"><header><span>'+String(index+1).padStart(2,'0')+'</span><h3>'+esc(item.item_name||tr('Inventory item','Artículo de inventario'))+'</h3>'+(item.url?'<img src="'+esc(item.url)+'" alt="'+esc(item.item_name||'')+'">':'')+'</header><dl>'+fields.map(([label,value])=>'<div><dt>'+esc(label)+'</dt><dd>'+esc(value??'—')+'</dd></div>').join('')+'</dl>'+(item.notes?'<p class="inventory-record-note"><b>'+tr('Notes:','Notas:')+'</b> '+esc(item.notes)+'</p>':'')+'</section>';
}
