async function backupCloudCall(body){
 const result=await db.functions.invoke('backup-cloud',{body});
 if(result.error){let message=result.data?.error;try{if(!message&&result.error.context)message=(await result.error.context.json()).error}catch{}throw Error(message||tr('Cloud connection could not be checked. Try again.','No se pudo comprobar la conexión. Inténtalo nuevamente.'))}
 if(result.data?.error)throw Error(result.data.error);return result.data;
}
async function cloudBackup(){const viewCurrent=captureView();
 if(state.profile.role!=='admin')return frame('<section class="card"><h1>'+tr('Admin access required','Acceso exclusivo de Admin')+'</h1></section>');
 const projectId=state.project,project=state.projects.find(p=>p.id===projectId);if(!project)return error(tr('Select a project first.','Seleccione un proyecto primero.'));
 const q=await db.from('cloud_backups').select('*').eq('project_id',projectId).order('created_at',{ascending:false}).limit(30);if(!viewCurrent())return;if(q.error)return error(q.error);
 let cloud,connectionError='';try{cloud=await backupCloudCall({action:'status',project_id:projectId})}catch(err){connectionError=err.message;cloud={provider:'supabase',providers:[],exports:[]}}
 if(state.project!==projectId||state.page!=='cloudBackup')return;
 const labels={supabase:tr('Local · PC / Tablet / Phone','Local · PC / Tablet / Teléfono'),google_drive:'Google Drive',dropbox:'Dropbox'},current=cloud.provider||'supabase',rows=q.data||[];
 const history=rows.length?rows.map(b=>{
  const exports=(cloud.exports||[]).filter(x=>x.backup_id===b.id),copy=exports.find(x=>x.provider===current);
  return '<div class="backup-row"><span class="backup-state '+esc(b.status)+'">'+(b.status==='completed'?'✓ ':'')+esc(b.status.toUpperCase())+'</span><div><b>'+esc(b.backup_number)+'</b><small>'+esc(fmt(b.created_at))+' · '+b.file_count+' files · '+formatBackupBytes(b.total_bytes)+'</small>'+(b.error_message?'<small>'+esc(b.error_message)+'</small>':'')+exports.map(x=>'<small>'+esc(labels[x.provider])+' · '+esc(x.status)+' · '+x.copied_count+'/'+x.total_files+(x.error_message?' · '+esc(x.error_message):'')+'</small>').join('')+'</div>'+(b.status==='completed'&&b.verified_at?'<button type="button" class="secondary" data-local="'+esc(b.id)+'">'+tr('Download ZIP','Descargar ZIP')+'</button>':'')+(b.manifest_path?'<button type="button" class="secondary" data-manifest="'+esc(b.manifest_path)+'">'+tr('Manifest','Manifest')+'</button>':'')+(current!=='supabase'&&b.status==='completed'&&copy?.status!=='completed'?'<button type="button" data-copy="'+esc(b.id)+'">'+tr('Copy / Resume to ','Copiar / Reanudar en ')+esc(labels[current])+'</button>':'')+'</div>';
 }).join(''):'<p class="empty-state">'+tr('No backups created yet.','Aún no se han creado respaldos.')+'</p>';
 const providerCards=['google_drive','dropbox'].map(p=>{const info=(cloud.providers||[]).find(x=>x.provider===p),connected=info?.connection;return '<article class="backup-provider-card"><h3>'+labels[p]+'</h3><p>'+esc(connected?.account_label||(!info?.configured?tr('Provider setup pending','Configuración del proveedor pendiente'):tr('Account not connected','Cuenta sin conectar')))+'</p><button type="button" data-connect="'+p+'" '+(!info?.configured?'disabled':'')+'>'+tr(connected?'Reconnect account':'Connect account',connected?'Reconectar cuenta':'Conectar cuenta')+'</button>'+(connected?'<button type="button" class="secondary" data-disconnect="'+p+'">'+tr('Disconnect','Desconectar')+'</button>':'')+(!info?.configured?'<details><summary>'+tr('Setup instructions','Instrucciones de configuración')+'</summary><p>'+tr('Create OAuth credentials for this app and save these secrets in Supabase:','Crea credenciales OAuth para esta app y guarda estos secretos en Supabase:')+'</p><code>'+(p==='google_drive'?'GOOGLE_BACKUP_CLIENT_ID<br>GOOGLE_BACKUP_CLIENT_SECRET':'DROPBOX_BACKUP_APP_KEY<br>DROPBOX_BACKUP_APP_SECRET')+'</code><p>'+tr('Authorized redirect URL:','URL de redirección autorizada:')+'</p><code class="backup-callback">'+esc(cloud.callback_url||'')+'</code><p>'+(p==='google_drive'?tr('Enable Drive API and use the drive.file permission.','Habilita Drive API y usa el permiso drive.file.'):tr('Use an App Folder app with file write, metadata read and account information permissions.','Usa una app de tipo App Folder con permisos de escritura, lectura de metadatos e información de la cuenta.'))+'</p></details>':'')+'</article>'}).join('')+'<article class="backup-provider-card"><h3>'+tr('Local · PC / Tablet / Phone','Local · PC / Tablet / Teléfono')+'</h3><p>'+tr('Download a verified ZIP with records, photos and saved PDFs. No external account needed.','Descarga un ZIP verificado con registros, fotos y PDFs guardados. No requiere cuenta externa.')+'</p><p>'+tr('Up to 200 MB per ZIP. Keep this page open. Save the file in Downloads or Files.','Hasta 200 MB por ZIP. Mantén esta página abierta. Guarda el archivo en Descargas o Archivos.')+'</p><button type="button" id="backup-local-select">'+tr('Select local backup','Seleccionar respaldo local')+'</button></article>';
 if(!viewCurrent())return;frame('<section class="backup-shell"><div class="backup-hero"><span>☁</span><div><small>G&E SAFETY DEPARTMENT</small><h1>'+tr('Cloud Backup Center','Centro de Respaldo en la Nube')+'</h1><p>'+tr('Manage the primary backup destination for this project.','Administra el destino principal de respaldos de este proyecto.')+'</p></div></div><div class="backup-status-card"><div><small>'+tr('CURRENT PROJECT','PROYECTO ACTUAL')+'</small><b>'+esc(project.name)+'</b></div><div><label for="backup-primary-storage"><small>'+tr('PRIMARY STORAGE · BACKUPS','ALMACENAMIENTO PRINCIPAL · RESPALDOS')+'</small></label><select id="backup-primary-storage" '+(connectionError?'disabled':'')+'>'+Object.entries(labels).map(([p,label])=>'<option value="'+p+'" '+(p===current?'selected':'')+' '+(p!=='supabase'&&!(cloud.providers||[]).find(x=>x.provider===p)?.connection?'disabled':'')+'>'+label+'</option>').join('')+'</select></div><div><small>'+tr('BACKUP ENGINE','MOTOR DE RESPALDO')+'</small><b>G&E Verified Backup v2</b></div></div><div class="backup-card"><p>'+tr('The selection is saved for this project. App records and evidence remain available through Supabase; the chosen provider receives backup copies.','La selección se guarda para este proyecto. Los registros y evidencias de la app siguen disponibles mediante Supabase; el proveedor elegido recibe copias de respaldo.')+'</p><div id="backup-progress" role="status" aria-live="polite">'+esc(connectionError)+'</div><button id="backup-refresh" type="button" class="secondary">'+tr('Refresh connection status','Actualizar estado de conexión')+'</button></div><div class="backup-card"><h2>'+tr('Create Verified Backup','Crear Respaldo Verificado')+'</h2><p>'+tr('Includes project records, JHA photos, inventory, orientation evidence and saved final PDFs. Keep this page open during an external copy; interrupted copies can be resumed from history.','Incluye registros, fotos de JHA, inventario, evidencia de orientación y PDFs finales guardados. Mantén esta página abierta durante la copia externa; puedes reanudarla desde el historial.')+'</p><button id="create-cloud-backup" class="backup-create" '+(connectionError?'disabled':'')+'>'+tr('Back Up This Project to ','Respaldar Este Proyecto en ')+esc(labels[current])+'</button></div><div class="backup-card"><h2>'+tr('Backup Destinations · Admin Only','Destinos de Respaldo · Solo Admin')+'</h2><div class="backup-connection-grid">'+providerCards+'</div><p class="backup-note">'+tr('Authorize only the account where you want to store this project’s backups. Credentials stay on the server. Disconnecting does not delete existing cloud files.','Autoriza únicamente la cuenta donde quieres guardar los respaldos de este proyecto. Las credenciales permanecen en el servidor. Desconectar no borra archivos existentes.')+'</p></div><div class="backup-card"><h2>'+tr('Backup History','Historial de Respaldos')+'</h2><div class="backup-history">'+history+'</div></div></section>');
 let busy=false;
 const active=()=>state.project===projectId&&state.page==='cloudBackup',setBusy=value=>{busy=value;document.querySelectorAll('.backup-shell button,.backup-shell select').forEach(button=>{if(button.id==='backup-refresh'||!button.disabled||button.dataset.backupBusy==='true'){button.disabled=value;if(value)button.dataset.backupBusy='true';else delete button.dataset.backupBusy}})};
 const progress=text=>{if(active()){const node=document.querySelector('#backup-progress');if(node)node.textContent=text}};
 const copy=async id=>{let result;do{if(!active())return;result=await backupCloudCall({action:'export',project_id:projectId,provider:current,backup_id:id});progress(tr('Copying to ','Copiando en ')+labels[current]+': '+result.copied_count+'/'+result.total_files)}while(!result.done)};
 let localReady=null;
 const local=async id=>{progress(tr('Preparing local ZIP…','Preparando ZIP local…'));const result=await backupCloudCall({action:'local_download',project_id:projectId,backup_id:id});localReady=await prepareLocalBackup(result,(done,total)=>progress(tr('Downloading and verifying ','Descargando y verificando ')+done+'/'+total));};
 const showLocal=()=>{if(!localReady||!active())return;const area=document.querySelector('#backup-progress'),link=document.createElement('a'),url=URL.createObjectURL(localReady.blob);link.href=url;link.download=localReady.name;link.className='button';link.textContent=tr('Save ZIP to this device','Guardar ZIP en este dispositivo');link.onclick=()=>confirmAction(tr('Backup ZIP download started.','Descarga del ZIP de respaldo iniciada.'));area.replaceChildren(link);setTimeout(()=>URL.revokeObjectURL(url),900000);};
 const run=async task=>{if(busy)return;setBusy(true);try{await task();savedAction('Backup action completed successfully.','Acción de respaldo completada correctamente.');if(active()){await cloudBackup();showLocal()}}catch(err){if(active()){await cloudBackup();error(err)}}finally{if(active())setBusy(false)}};
 document.querySelector('#backup-local-select').onclick=()=>run(()=>backupCloudCall({action:'select',project_id:projectId,provider:'supabase'}));
 document.querySelectorAll('[data-local]').forEach(button=>button.onclick=()=>run(()=>local(button.dataset.local)));
 document.querySelector('#backup-refresh').onclick=()=>{if(!busy)cloudBackup()};
 document.querySelector('#backup-primary-storage').onchange=e=>{const provider=e.target.value;run(()=>backupCloudCall({action:'select',project_id:projectId,provider}))};
 document.querySelector('#create-cloud-backup').onclick=()=>run(async()=>{progress(tr('Creating and verifying local backup…','Creando y verificando respaldo local…'));const result=await db.functions.invoke('create-cloud-backup',{body:{project_id:projectId}});if(result.error||!result.data?.ok)throw Error(result.data?.error||result.error?.message||tr('Backup failed','El respaldo falló'));if(current!=='supabase')await copy(result.data.id);else await local(result.data.id)});
 document.querySelectorAll('[data-copy]').forEach(button=>button.onclick=()=>run(()=>copy(button.dataset.copy)));
 document.querySelectorAll('[data-disconnect]').forEach(button=>button.onclick=()=>run(()=>backupCloudCall({action:'disconnect',project_id:projectId,provider:button.dataset.disconnect})));
 document.querySelectorAll('[data-connect]').forEach(button=>button.onclick=async()=>{
  if(busy)return;const provider=button.dataset.connect,popup=window.open('about:blank','ge_backup_connect','popup,width=650,height=750');
  try{setBusy(true);const result=await backupCloudCall({action:'connect',project_id:projectId,provider});if(!popup){progress(tr('Popup blocked. Allow popups and choose Connect account again.','Ventana bloqueada. Permite ventanas emergentes y vuelve a elegir Conectar cuenta.'));return}popup.location.href=result.authorization_url;let ticks=0;const poll=setInterval(()=>{if(++ticks>300||!active()){clearInterval(poll);return}if(popup.closed){clearInterval(poll);cloudBackup()}},2000);}
  catch(err){popup?.close();error(err)}finally{if(active())setBusy(false)}
 });
 document.querySelectorAll('[data-manifest]').forEach(button=>button.onclick=async()=>{const result=await db.storage.from('cloud-backups').createSignedUrl(button.dataset.manifest,120);if(result.error)return error(result.error);window.open(result.data.signedUrl,'_blank','noopener')});
}
function formatBackupBytes(n){n=Number(n||0);if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';if(n<1073741824)return (n/1048576).toFixed(1)+' MB';return (n/1073741824).toFixed(2)+' GB'}

