 skid_steer:{name:'Skid Steer / Bobcat',ref:'29 CFR 1926.602 and manufacturer requirements',items:['Tires / tracks and wheel condition','Bucket / attachment and locking system','Lift arms / cylinders / hydraulic leaks','ROPS / FOPS structure condition','Seat belt and operator restraint bar','Interlocks / controls functional','Horn / backup alarm','Lights / gauges','Steps / grab handles clean and secure','No unauthorized modifications or operational defects']},
