const safetyTools=createSafetyTools({db,state,tr,frame,navigate,captureView,error,confirmAction,enableAutoDraft,draftFilesFor,clearDraft,normalizeReportImage,signedDisplayImage});
window.addEventListener('popstate',e=>{safetyTools.stop();if(!state.session)return;flushActiveDrafts();const h=e.state;if(h?.geSafety){restoringHistory=true;state.page=h.page||'home';state.detail=h.detail||null;render();restoringHistory=false}else if(state.page!=='home'){navigate('home',null,{replace:true})}});
db?.auth.onAuthStateChange((event,session)=>{
  // Startup already calls refresh. Token renewal and returning to the tab must
  // not fetch the dashboard again or replace a form the user is completing.
  if(event==='INITIAL_SESSION')return;
  if((event==='TOKEN_REFRESHED'||event==='SIGNED_IN')&&session?.user?.id===state.session?.user?.id){
    state.session=session;return;
  }
  if(event==='PASSWORD_RECOVERY')state.page='setPassword';
  setTimeout(()=>{
    if(state.session&&!history.state?.geSafety)history.replaceState({geSafety:true,page:state.page,detail:state.detail},'',location.href);
    refresh();
  },0);
});refresh();
